{"name":"WeightedGradeInput","type":"delimited","fields":[{"name":"course_id","type":"integer","nullable":false},{"name":"mark","type":"decimal"},{"name":"credit","type":"long","nullable":false}]}
Accumulator:
{"name":"WeightedGradeState","type":"delimited","fields":[{"name":"weighted","type":"decimal"},{"name":"credits","type":"long","nullable":false}]}
Output 0:
{"name":"WeightedGradeSummary","type":"delimited","fields":[{"name":"course_id","type":"integer","nullable":false},{"name":"result","type":"decimal","nullable":true,"length":18,"scale":2}]}
Validate this complete Rollup against its metadata and requirements.
```ctl
//#CTL2
function void initGroup(WeightedGradeState acc) {
    acc.weighted = 0D;
    acc.credits = 0L;
}
function boolean updateGroup(WeightedGradeState acc) {
    if (!isnull($in.0.mark) && $in.0.mark > 0D && $in.0.credit > 0L) {
        acc.weighted += $in.0.mark * $in.0.credit;
        acc.credits += $in.0.credit;
    }
    return false;
}
function integer updateTransform(integer counter, WeightedGradeState acc) {
    return SKIP;
}
function integer transform(integer counter, WeightedGradeState acc) {
    if (counter > 0) return SKIP;
    $out.0.course_id = $in.0.course_id;
    $out.0.result = acc.credits == 0L ? null : round(acc.weighted / acc.credits, 2);
    return ALL;
}
```

